(6287086, 929901, 117804, '<td valign="top">funny set up, however the background is too much ''visible'' IMHO</td>', 'funny set up, however the background is too much ''visible'' IMHO', '2011-01-18 16:51:46.000000', NULL, 1),
(6287089, 930243, 117804, '<td valign="top">nice set up...</td>', 'nice set up...', '2011-01-18 16:53:15.000000', NULL, 1),
