(6287311, 930086, 124815, '<td valign="top">Enviable situation!</td>', 'Enviable situation!', '2011-01-18 21:12:58.000000', NULL, 1),
(6287430, 930261, 122290, '<td valign="top">Awesome creative idea</td>', 'Awesome creative idea', '2011-01-18 23:34:56.000000', NULL, 1),
(6287431, 930083, 122290, '<td valign="top">LOL! Funny concept.</td>', 'LOL! Funny concept.', '2011-01-18 23:35:45.000000', NULL, 1),
(6287433, 929418, 122290, '<td valign="top">Awesome!!</td>', 'Awesome!!', '2011-01-18 23:36:51.000000', NULL, 1),
