(6287559, 930366, 125659, '<td valign="top">Really cool idea. Obviously there are 3 sources of light, but I think the duck needs more lighting on him.</td>', 'Really cool idea. Obviously there are 3 sources of light, but I think the duck needs more lighting on him.', '2011-01-19 01:00:04.000000', NULL, 1),
(6287571, 930291, 125659, '<td valign="top">Awesome job on the balancing of the duck. Im guessing you used toothpicks on the vegetables and propped something behind the duck to keep it all in place.</td>', 'Awesome job on the balancing of the duck. Im guessing you used toothpicks on the vegetables and propped something behind the duck to keep it all in place.', '2011-01-19 01:03:06.000000', NULL, 1),
(6287574, 930290, 125659, '<td valign="top">Lol, nice title</td>', 'Lol, nice title', '2011-01-19 01:04:06.000000', NULL, 1),
(6287693, 930284, 99708, '<td valign="top">He lays eggs?</td>', 'He lays eggs?', '2011-01-19 01:46:14.000000', NULL, 1),
(6287856, 930363, 108069, '<td valign="top">Shell on his head like a helmet is a nice touch. Cute scene, interesting composition.</td>', 'Shell on his head like a helmet is a nice touch. Cute scene, interesting composition.', '2011-01-19 06:31:36.000000', NULL, 1),
(6287857, 930261, 108069, '<td valign="top">More brilliance. You really need to do lighting seminars for people. It''s simply perfect. Creative idea, again. Excellent.</td>', 'More brilliance. You really need to do lighting seminars for people. It''s simply perfect. Creative idea, again. Excellent.', '2011-01-19 06:32:55.000000', NULL, 1),
(6287859, 930245, 108069, '<td valign="top">I don''t quite follow. He''s caroling and you want him gone? Regardless, the cauliflower snow is nice. Elements all work well together. Good composition.</td>', 'I don''t quite follow. He''s caroling and you want him gone? Regardless, the cauliflower snow is nice. Elements all work well together. Good composition.', '2011-01-19 06:34:32.000000', NULL, 1),
(6287948, 930246, 108069, '<td valign="top">Poor guy isn''t even paying attention. A little bit soft, but nicely conceived.</td>', 'Poor guy isn''t even paying attention. A little bit soft, but nicely conceived.', '2011-01-19 08:11:52.000000', NULL, 1),
(6287950, 930366, 108069, '<td valign="top">A weird scene that weirdly works.</td>', 'A weird scene that weirdly works.', '2011-01-19 08:12:37.000000', NULL, 1),
