(6287986, 930261, 53557, '<td valign="top">LOL! Very creative!</td>', 'LOL! Very creative!', '2011-01-19 08:26:30.000000', NULL, 1),
(6288037, 930071, 111119, '<td valign="top">Angry birds eat your heart out!</td>', 'Angry birds eat your heart out!', '2011-01-19 09:16:26.000000', NULL, 1),
(6288076, 930209, 108069, '<td valign="top">Poor duck. Nicely composed. Simple and very well done.</td>', 'Poor duck. Nicely composed. Simple and very well done.', '2011-01-19 09:45:31.000000', NULL, 1),
(6288080, 930208, 43463, '<td valign="top">Nice idea and wonderfully put together. Nice details, great colors and the lighting is wonderful. A lucky coincidence or mayhap you searched for the right duck -- the expression is great for the ducky really does look happy to have caught the fish:-)</td>', 'Nice idea and wonderfully put together. Nice details, great colors and the lighting is wonderful. A lucky coincidence or mayhap you searched for the right duck -- the expression is great for the ducky really does look happy to have caught the fish:-)', '2011-01-19 09:47:16.000000', NULL, 1),
(6288095, 930099, 36843, '<td valign="top">Very funny</td>', 'Very funny', '2011-01-19 09:55:12.000000', NULL, 1),
(6288097, 930188, 43463, '<td valign="top">That''s one angry duck (I don''t think I have ever seen a ducky with angry eyebrows)! My free associating mind had the momentary thought "Hassan CHOP!" pop into my head; but that''s Daffy Duck not the Duckterogator. Wonder what info the Duckterrogator is trying to extract from the pepper...perhaps he is looking for it to spill it''s Scoville rating;-P Lighting and set up are all done well.</td>', 'That''s one angry duck (I don''t think I have ever seen a ducky with angry eyebrows)! My free associating mind had the momentary thought "Hassan CHOP!" pop into my head; but that''s Daffy Duck not the Duckterogator. Wonder what info the Duckterrogator is trying to extract from the pepper...perhaps he is looking for it to spill it''s Scoville rating;-P Lighting and set up are all done well.', '2011-01-19 09:56:11.000000', NULL, 1),
(6288106, 930294, 43463, '<td valign="top">Oh my! So as I see it this is the start of another Hatfield vs McCoys family feud...Woodies vs. Duckies;-) Tis a twisted humor take on those who favor woodies over duckies. Very creative use of the green onions as the trees. Lighting is good with all elements well lit. Not my usual cup of tea but well done and in the above average category...or should that be cate<b>gory</b>;-P</td>', 'Oh my! So as I see it this is the start of another Hatfield vs McCoys family feud...Woodies vs. Duckies;-) Tis a twisted humor take on those who favor woodies over duckies. Very creative use of the green onions as the trees. Lighting is good with all elements well lit. Not my usual cup of tea but well done and in the above average category...or should that be category;-P', '2011-01-19 10:06:37.000000', NULL, 1),
(6288110, 930261, 36843, '<td valign="top">Omg you have done it again, this is just great, makes my laugh</td>', 'Omg you have done it again, this is just great, makes my laugh', '2011-01-19 10:10:25.000000', NULL, 1),
